from zipfile import ZipFile, ZIP_DEFLATED
from lxml import etree
from copy import deepcopy
from pathlib import Path
src=Path('output/turn-3-redline-gmra.docx'); tmp=Path('output/turn-3-redline-gmra.tmp.docx')
W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'; NS={'w':W}
def q(n): return f'{{{W}}}{n}'
def visible(p): return ''.join(p.xpath('.//w:t/text()',namespaces=NS))
def clone_rpr(p):
 r=p.find(q('r'))
 if r is not None and r.find(q('rPr')) is not None: return deepcopy(r.find(q('rPr')))
 rp=etree.Element(q('rPr')); f=etree.SubElement(rp,q('rFonts')); f.set(q('ascii'),'Times New Roman'); f.set(q('hAnsi'),'Times New Roman'); s=etree.SubElement(rp,q('sz')); s.set(q('val'),'22'); return rp
def run(p,text,deleted=False):
 r=etree.Element(q('r')); r.append(clone_rpr(p)); t=etree.SubElement(r,q('delText') if deleted else q('t')); t.text=text; t.set('{http://www.w3.org/XML/1998/namespace}space','preserve'); return r
def clear(p):
 for c in list(p):
  if c.tag!=q('pPr'): p.remove(c)
def cont(p,kind,text):
 e=etree.Element(q(kind)); e.set(q('id'),str(cont.n)); cont.n+=1; e.set(q('author'),'Pryor, Ashworth & Gelb LLP'); e.set(q('date'),'2025-04-17T17:00:00Z'); e.append(run(p,text,kind=='del')); p.append(e)
cont.n=3000
def rep(p,new):
 old=visible(p); clear(p); cont(p,'del',old); cont(p,'ins',new)
with ZipFile(src) as z: files={n:z.read(n) for n in z.namelist()}
root=etree.fromstring(files['word/document.xml']); ps=root.xpath('//w:body/w:p',namespaces=NS)
rep(ps[273],'(c) "Cross-Default Threshold" means, with respect to each party, $25,000,000 (twenty-five million United States Dollars) (or its equivalent in any other currency, converted into the Base Currency at the spot rate of exchange at the relevant time).')
rep(ps[277],'(b) Grace Period: Fifteen (15) Business Days. An Act of Insolvency shall not constitute an Event of Default unless it has continued unremedied for a period of fifteen (15) Business Days following the date on which the Non-Defaulting Party first becomes aware of, or receives written notice of, such Act of Insolvency (the "Act of Insolvency Grace Period").')
rep(ps[297],'(a) Buyer may, at its sole option, elect to reprice any Transaction having an original term or, in the case of an evergreen or rolling Transaction, a then-current term, exceeding sixty (60) calendar days. Such repricing (a "Repricing Event") may be exercised on the 90th calendar day following the Purchase Date of the relevant Transaction, or on the date of the first quarterly anniversary of the Purchase Date, whichever is later (each such date, a "Repricing Date"). If a Repricing Date falls on a day that is not a Business Day, it shall be the next following Business Day.')
rep(ps[298],'(b) Buyer shall exercise a Repricing Event by delivering written notice to Seller not less than two (2) Business Days prior to the applicable Repricing Date. The notice shall specify the Transaction to be repriced and the proposed Repricing Date.')
rep(ps[299],'(c) Upon the occurrence of a Repricing Event, the original Transaction shall terminate on the Repricing Date as if such date were the Repurchase Date, and the parties shall simultaneously enter into a new Transaction on terms identical to the original Transaction, save that the Purchase Price shall be recalculated based on the Market Value of the Purchased Securities on the Repricing Date after application of the relevant Haircut Percentage. Any close-out amount arising from the termination of the original Transaction and commencement of the new Transaction shall be the difference between the Repurchase Price of the original Transaction and the Purchase Price of the new Transaction and shall be settled in cash on the Repricing Date. The repricing mechanic does not affect either party\'s rights under Paragraph 4 or Paragraph 10.')
files['word/document.xml']=etree.tostring(root,xml_declaration=True,encoding='UTF-8',standalone=True)
with ZipFile(tmp,'w',ZIP_DEFLATED) as z:
 for n,d in files.items(): z.writestr(n,d)
tmp.replace(src)
print('patched')
